/// The fa1.dev App Store surfaces (issues #691 + #881) — CI pins so the
/// site can never drift from the single source of truth:
///
///  * the homepage App Store block, the header badge, and the hero CTA
///    (between their generated markers in site/index.html) are byte-equal
///    to what the renderers emit for the DEFAULT `links:` config — change
///    a default without running `dart run scripts/regen_site_store_block.dart`
///    and this fails (AC1/AC4: one change, every placement);
///  * the store-frames page (site/app-store/index.html) links the same
///    default URLs and carries store-referral placements;
///  * the frames page shows EXACTLY the committed en/ios store goldens —
///    no hand-copied PNGs, no stray images, none missing (AC3), and the
///    Pages deploy copies them from the golden tree (pinned below);
///  * no superlative claims on either surface (AC6 — the issue #643
///    compliance list applies to the site and banners too).
library;

import 'dart:io';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

void main() {
  final index = File('site/index.html').readAsStringSync();
  final framesPage = File('site/app-store/index.html').readAsStringSync();
  final pagesWorkflow = File('.github/workflows/pages.yml').readAsStringSync();
  final goldenDir = Directory('flutter_app/test/goldens/store/en/ios');

  /// The banned-claim list from the store copy gate (issue #643) —
  /// applied here to the site surfaces. Hyphenated compounds
  /// (`margin-top` in the page CSS) are stripped first, exactly like
  /// the store gate.
  final compound = RegExp(r'[A-Za-zА-Яа-яЁё0-9]+(?:-[A-Za-zА-Яа-яЁё0-9]+)+');
  final banned = RegExp(
    '(?<![A-Za-zА-Яа-яЁё0-9])(first|best|top|leading|most|#1|№1|'
    'первый|лучший|самый)(?![A-Za-zА-Яа-яЁё0-9])',
    caseSensitive: false,
  );

  List<String> violations(String text) => banned
      .allMatches(text.replaceAll(compound, ' '))
      .map((m) => m.group(0)!)
      .toList();

  test('the committed homepage block is the generated one (AC1)', () {
    final start = index.indexOf(appStoreBlockStartMarker);
    final end = index.indexOf(appStoreBlockEndMarker);
    expect(start, greaterThan(0), reason: 'start marker missing');
    expect(end, greaterThan(start), reason: 'end marker missing');
    final committed = index

  factory LinksConfig.fromYaml(Object? node) {
    if (node == null) return const LinksConfig();
    if (node is! YamlMap) {
      throw ConfigException(
        '"links" must be a map of product links, got: $node',
      );
    }
    final notes = <String>[];
    String appstore = defaultAppStoreUrl;
    String testflight = defaultTestFlightUrl;
    String? play;
    String apkGod = defaultApkGodUrl;
    String apkStandard = defaultApkStandardUrl;
    String site = defaultSiteUrl;
    bool banner = true;
    node.forEach((key, value) {
      switch ('$key') {
        case 'appstore':
          appstore = _link('$key', value);
        case 'testflight':
          testflight = _link('$key', value);
        case 'play':
          play = value == null ? null : _link('$key', value);
        case 'apk-god':
          apkGod = _link('$key', value);
        case 'apk-standard':
          apkStandard = _link('$key', value);
        case 'site':
          site = _link('$key', value);
        case 'banner':
          if (value is! bool) {
            throw ConfigException('"links.banner" must be a boolean');
          }
          banner = value;
        default:
          notes.add('links.$key: unknown key (ignored)');
      }
    });
    return LinksConfig(
      appstore: appstore,
      testflight: testflight,
      play: play,
      apkGod: apkGod,
      apkStandard: apkStandard,
      site: site,
      banner: banner,
      notes: List.unmodifiable(notes),
    );
  }

  /// Known link keys must be non-empty http(s) URLs.
  static String _link(String key, Object? value) {
    if (value is! String || value.trim().isEmpty) {
      throw ConfigException('"links.$key" must be a non-empty URL string');
    }
    if (!value.startsWith('https://') && !value.startsWith('http://')) {
      throw ConfigException('"links.$key" must be an http(s) URL, got: $value');
    }
    return value.trim();
  }

  /// Renders the section, only the non-default keys (defaults are never
  /// written — the file stays minimal).
  String toYaml() {
    final buffer = StringBuffer('links:\n');
    // URLs are double-quoted: a value like "https://ex/app #frag" (space
    // before the fragment) parses back truncated if written bare — the
    // quote keeps the strict round-trip safe for every accepted value.
    if (appstore != defaultAppStoreUrl) {
      buffer.write('  appstore: "$appstore"\n');
    }
    if (testflight != defaultTestFlightUrl) {
      buffer.write('  testflight: "$testflight"\n');
    }
    if (play != null) buffer.write('  play: "$play"\n');
    if (apkGod != defaultApkGodUrl) {
      buffer.write('  apk-god: "$apkGod"\n');
    }
    if (apkStandard != defaultApkStandardUrl) {
      buffer.write('  apk-standard: "$apkStandard"\n');
    }
    if (site != defaultSiteUrl) buffer.write('  site: "$site"\n');
    if (!banner) buffer.write('  banner: false\n');
    return buffer.toString();
  }
}

